export default "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"robots\" content=\"noindex,nofollow\"><meta name=\"theme-color\" content=\"#facc15\">\n<title>Admin TAWON.MY.ID</title>\n<script src=\"https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.57.4\"></script>\n<style>\n:root{--yellow:#facc15;--ink:#171717;--muted:#737373;--line:#e5e5e5;--bg:#f5f5f4;--white:#fff;--green:#15803d;--red:#b91c1c}\n*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 system-ui,-apple-system,Segoe UI,sans-serif}button,input,textarea,select{font:inherit}button{cursor:pointer;border:0;border-radius:10px;padding:11px 15px;font-weight:750}.primary{background:var(--yellow);color:#111}.dark{background:#171717;color:#fff}.light{background:#f5f5f5;border:1px solid var(--line)}.danger{color:var(--red);background:#fee2e2}.muted{color:var(--muted)}.wrap{max-width:1250px;margin:auto;padding:18px}.top{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:18px}.brand{display:flex;align-items:center;gap:12px;font-weight:900;font-size:22px}.bee{background:var(--yellow);border:2px solid #111;border-radius:12px;padding:7px 10px}.badge{display:inline-block;border-radius:99px;background:#fef3c7;padding:4px 9px;font-size:12px;font-weight:800}.layout{display:grid;grid-template-columns:220px 1fr;gap:18px}.side,.panel,.card{background:#fff;border:1px solid var(--line);border-radius:16px}.side{padding:12px;height:max-content;position:sticky;top:12px}.navbtn{display:block;width:100%;text-align:left;background:transparent;padding:12px;margin:3px 0}.navbtn.active,.navbtn:hover{background:#fef3c7}.main{min-width:0}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:16px}.card{padding:17px}.statnum{font-size:27px;font-weight:900}.panel{padding:20px;margin-bottom:16px}.panel h2{margin:0 0 16px;font-size:21px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.field{display:flex;flex-direction:column;gap:6px;margin-bottom:13px}.field label{font-size:13px;font-weight:800}.field input,.field textarea,.field select{width:100%;border:1px solid #d4d4d4;border-radius:10px;padding:11px;background:#fff;min-width:0}.password-wrap{display:flex;gap:0}.password-wrap input{flex:1;min-width:0;border-radius:10px 0 0 10px}.password-toggle{border:1px solid #d4d4d4;border-left:0;border-radius:0 10px 10px 0;background:#f5f5f5;padding:0 14px;font-size:18px}.field textarea{min-height:115px;resize:vertical}.field .short{min-height:70px}.field small{color:var(--muted)}.full{grid-column:1/-1}.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.notice{padding:12px 14px;border-radius:10px;background:#fef3c7;margin:10px 0}.success{background:#dcfce7}.error{background:#fee2e2}.hidden{display:none!important}.thumb{width:100%;max-height:280px;object-fit:cover;border-radius:12px;background:#f5f5f5}.tablewrap{overflow:auto}table{border-collapse:collapse;width:100%;min-width:600px}th,td{padding:11px;border-bottom:1px solid var(--line);text-align:left}th{font-size:12px;text-transform:uppercase;color:var(--muted)}.status{font-size:12px;font-weight:800;border-radius:99px;padding:4px 8px;background:#eee}.status.published{background:#dcfce7;color:#166534}.status.review{background:#dbeafe;color:#1d4ed8}.login{max-width:470px;margin:7vh auto}.login .panel{padding:26px}.login h1{margin:0 0 6px}.chip{display:inline-flex;gap:7px;align-items:center;background:#f5f5f5;border:1px solid var(--line);padding:7px 9px;border-radius:9px;margin:3px}.chip button{padding:0;background:none}.editorbar{display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap}.wordcount{font-size:12px;color:var(--muted)}@media(max-width:800px){.layout{grid-template-columns:1fr}.side{position:static;display:flex;overflow:auto;gap:5px}.navbtn{white-space:nowrap;width:auto}.stats{grid-template-columns:1fr 1fr}.grid{grid-template-columns:1fr}.full{grid-column:auto}.wrap{padding:10px}.panel{padding:14px}.top{align-items:flex-start}.brand{font-size:18px}}@media(max-width:430px){.stats{grid-template-columns:1fr}.top .row{justify-content:flex-end}}\n\n/* Editorial control room */\n.top .badge{color:#513f00}.rank-row a{color:inherit;text-decoration:none}.rank-row a:hover{text-decoration:underline}\nbody{background:#f3f5f7;font-size:14px}.wrap{max-width:1540px;padding:26px}.top{background:#101619;color:white;padding:18px 24px;margin:-26px -26px 26px;min-height:85px}.top a{color:#facc15!important}.brand{font-size:21px;letter-spacing:-.7px}.bee{background:transparent;border:0;padding:0}.bee img{width:44px;height:44px}.top .muted{color:#b2bac0}.layout{grid-template-columns:230px minmax(0,1fr);gap:24px}.side{background:#101619;border:0;border-radius:15px;padding:14px 10px;min-height:78vh;color:#b6c0c7}.side:before{content:'EDITORIAL DESK';display:block;font-size:10px;letter-spacing:2px;color:#707e88;padding:15px}.navbtn{color:inherit;font-weight:600;font-size:13px;margin:5px 0;padding:13px 15px;border-radius:8px}.navbtn.active,.navbtn:hover{background:#facc15;color:#111}.panel,.card{border-color:#e7ebee;border-radius:12px;box-shadow:0 2px 5px #15202b03}.panel{padding:23px}.panel h2{font-size:17px}.stats{grid-template-columns:repeat(4,minmax(0,1fr));gap:15px}.statnum{font-size:32px;letter-spacing:-1px;margin-top:8px}.card .muted{font-size:12px}.card{border-top:3px solid #facc15}.dashboard-heading{display:flex;justify-content:space-between;gap:15px;align-items:center;margin:0 0 22px}.dashboard-heading h1{font-size:25px;margin:0}.eyebrow{font-size:10px;color:#929ba2;letter-spacing:1.5px;font-weight:800}.dash-grid{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(230px,1fr);gap:18px}.quick-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.quick-grid button{background:#f8fafb;border:1px solid #e8edf0;min-height:85px;font-size:12px}.quick-grid button span{display:block;font-size:23px;margin-bottom:8px}.chart-bars{height:190px;display:flex;align-items:end;gap:12px;padding-top:16px}.chart-col{flex:1;min-width:0;text-align:center;font-size:11px;color:#737b83}.chart-col i{display:block;background:linear-gradient(#facc15,#fff2b5);border-top:3px solid #e6b800;min-height:2px;margin:6px auto;width:65%;border-radius:5px 5px 0 0}.chart-col b{color:#20272d}.rank-row{display:flex;gap:12px;padding:13px 0;border-bottom:1px solid #eef1f3;align-items:center}.rank-row img{width:55px;height:44px;object-fit:cover;border-radius:6px}.rank-row strong{font-size:12px;display:block}.rank-row small{font-size:11px;color:#7d858b}.media-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.media-item{border:1px solid #e6e9ed;border-radius:10px;padding:10px;overflow:hidden}.media-item img{width:100%;height:140px;object-fit:cover;border-radius:6px}.media-item input{width:100%;font-size:11px}.status.archived{background:#e5e7eb}.page-caption{margin:-7px 0 22px;color:#7a838b}.settings-preview{background:#101619;color:white;padding:24px;border-radius:12px;border-bottom:5px solid #facc15;margin-bottom:20px}.settings-preview h3{margin:0;font-size:23px}button:disabled{opacity:.5;cursor:wait}input:focus,textarea:focus,select:focus{outline:2px solid #facc15;outline-offset:2px}.login{max-width:490px}.login .brand{margin-bottom:15px}.login .panel{border-top:4px solid #facc15}.hidden{display:none!important}@media(max-width:1000px){.layout{grid-template-columns:185px 1fr}.dash-grid{grid-template-columns:1fr}.stats{grid-template-columns:repeat(2,1fr)}}@media(max-width:760px){.wrap{padding:14px}.top{margin:-14px -14px 18px;padding:14px;flex-wrap:wrap}.layout{grid-template-columns:1fr}.side{min-height:auto;display:flex;position:static;overflow:auto;padding:6px}.side:before{display:none}.navbtn{padding:11px;white-space:nowrap;flex-shrink:0;width:auto}.stats{grid-template-columns:repeat(2,1fr)}.quick-grid{grid-template-columns:repeat(2,1fr)}.media-grid{grid-template-columns:repeat(2,1fr)}.dashboard-heading{align-items:flex-start}.panel{padding:16px}.brand{font-size:18px}}\n</style>\n<link rel=\"manifest\" href=\"/manifest.webmanifest\"><link rel=\"icon\" type=\"image/png\" sizes=\"48x48\" href=\"/assets/favicon-v6.png\"><link rel=\"apple-touch-icon\" sizes=\"180x180\" href=\"/assets/apple-touch-icon-v6.png\"><meta name=\"apple-mobile-web-app-capable\" content=\"yes\"><meta name=\"apple-mobile-web-app-status-bar-style\" content=\"black-translucent\"><meta name=\"apple-mobile-web-app-title\" content=\"TAWON\"><link rel=\"stylesheet\" href=\"/pwa.css?v=8\"><link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.7.2/css/all.min.css\"><link rel=\"stylesheet\" href=\"/site-ui.css?v=8\"><script src=\"/editorial-standard.js?v=25\"></script></head>\n<body>\n<div id=\"loginView\" class=\"wrap login\">\n <div class=\"brand\"><span class=\"bee\"><img src=\"/assets/icon-192-v6.png\" alt=\"\"></span><span>TAWON.MY.ID <span class=\"muted\">Admin</span></span></div>\n <div class=\"panel\" style=\"margin-top:20px\">\n  <h1 id=\"authTitle\">Go to dashboard</h1><p class=\"muted\" id=\"authSubtitle\">Manage articles, thumbnails, categories, tags, and SEO.</p>\n  <div id=\"authNotice\" class=\"notice hidden\"></div>\n  <form id=\"authForm\">\n   <div class=\"field\"><label for=\"authEmail\">Email</label><input id=\"authEmail\" type=\"email\" autocomplete=\"email\" required></div>\n   <div class=\"field\"><label for=\"authPassword\">Password</label><div class=\"password-wrap\"><input id=\"authPassword\" type=\"password\" autocomplete=\"current-password\" minlength=\"8\" required><button id=\"togglePassword\" class=\"password-toggle\" type=\"button\" aria-label=\"Show password\" aria-pressed=\"false\"><i class=\"fa-solid fa-eye\" aria-hidden=\"true\"></i></button></div></div>\n   <button class=\"primary\" style=\"width:100%\" id=\"authSubmit\">Login</button>\n  </form>\n  <div style=\"display:flex;align-items:center;gap:10px;margin:16px 0;color:#737373;font-size:12px\"><span style=\"height:1px;background:#e5e5e5;flex:1\"></span>OR<span style=\"height:1px;background:#e5e5e5;flex:1\"></span></div>\n  <button id=\"googleLogin\" class=\"light\" style=\"width:100%\"><i class=\"fa-solid fa-circle\" aria-hidden=\"true\"></i> Continue with Google</button>\n  <p class=\"muted\" style=\"font-size:13px\">Google Login must be enabled in Supabase settings first.</p>\n  <p class=\"muted\" style=\"font-size:13px\"><button id=\"forgotPassword\" class=\"light\" type=\"button\">Forgot password?</button></p>\n  <p class=\"muted\" style=\"font-size:13px\">Don't have an account? <button id=\"toggleAuth\" class=\"light\" type=\"button\">Register account</button></p>\n  <p class=\"muted\" style=\"font-size:12px\">New accounts are automatically assigned the author role and cannot publish articles until approved by an admin.</p>\n </div>\n</div>\n<div id=\"forgotView\" class=\"wrap login hidden\">\n <div class=\"brand\"><span class=\"bee\"><img src=\"/assets/icon-192-v6.png\" alt=\"\"></span><span>TAWON.MY.ID <span class=\"muted\">Admin</span></span></div>\n <div class=\"panel\" style=\"margin-top:20px\">\n  <div style=\"font-size:34px;margin-bottom:8px\" aria-hidden=\"true\"><i class=\"fa-solid fa-lock\" aria-hidden=\"true\"></i></div>\n  <h1 style=\"margin-bottom:6px\">Forgot password?</h1>\n  <p class=\"muted\">Enter your account email address. We will send a link to create a new password.</p>\n  <div id=\"forgotNotice\" class=\"notice hidden\" role=\"status\" aria-live=\"polite\"></div>\n  <form id=\"forgotForm\">\n   <div class=\"field\"><label for=\"forgotEmail\">Email address</label><input id=\"forgotEmail\" type=\"email\" autocomplete=\"email\" placeholder=\"name@example.com\" required></div>\n   <button class=\"primary\" id=\"forgotSubmit\" type=\"submit\" style=\"width:100%\">Send reset link</button>\n  </form>\n  <button id=\"forgotBack\" class=\"light\" type=\"button\" style=\"width:100%;margin-top:10px\"><i class=\"fa-solid fa-arrow-left\" aria-hidden=\"true\"></i> Back to login</button>\n  <p class=\"muted\" style=\"font-size:12px;margin:16px 0 0\">Not receiving email? Check your spam folder and ensure the email address is correct.</p>\n </div>\n</div>\n<div id=\"resetView\" class=\"wrap login hidden\">\n <div class=\"brand\"><span class=\"bee\"><img src=\"/assets/icon-192-v6.png\" alt=\"\"></span><span>TAWON.MY.ID <span class=\"muted\">Reset Password</span></span></div>\n <div class=\"panel\" style=\"margin-top:20px\">\n  <h1>Set new password</h1>\n  <p class=\"muted\">Enter a new password for your account.</p>\n  <div id=\"resetNotice\" class=\"notice hidden\" role=\"status\" aria-live=\"polite\"></div>\n  <form id=\"resetForm\">\n   <div class=\"field\"><label for=\"newPassword\">New password</label><input id=\"newPassword\" type=\"password\" autocomplete=\"new-password\" minlength=\"8\" required></div>\n   <div class=\"field\"><label for=\"confirmPassword\">Repeat new password</label><input id=\"confirmPassword\" type=\"password\" autocomplete=\"new-password\" minlength=\"8\" required></div>\n   <button class=\"primary\" id=\"resetSubmit\" type=\"submit\" style=\"width:100%\">Save new password</button>\n  </form>\n  <p><button id=\"backToLogin\" class=\"light\" type=\"button\">Back to login page</button></p>\n </div>\n</div>\n<div id=\"appView\" class=\"wrap hidden\">\n <header class=\"top\"><div class=\"brand\"><span class=\"bee\"><img src=\"/assets/icon-192-v6.png\" alt=\"\"></span><span>TAWON.MY.ID <span class=\"muted\">CMS</span></span></div><div class=\"row\"><span id=\"userBadge\" class=\"badge\"></span><a href=\"/\" style=\"color:#111\">View site <i class=\"fa-solid fa-arrow-up-right-from-square\" aria-hidden=\"true\"></i></a><button id=\"logout\" class=\"light\">Logout</button></div></header>\n <div id=\"globalNotice\" class=\"notice hidden\"></div>\n <div class=\"layout\">\n  <aside class=\"side\">\n   <button class=\"navbtn active\" data-page=\"dashboard\"><i class=\"fa-solid fa-chart-pie\" aria-hidden=\"true\"></i> Dashboard</button>\n   <button class=\"navbtn\" data-page=\"editor\"><i class=\"fa-solid fa-pen-to-square\" aria-hidden=\"true\"></i> Write article</button>\n   <button class=\"navbtn\" data-page=\"articles\"><i class=\"fa-solid fa-newspaper\" aria-hidden=\"true\"></i> All articles</button>\n   <button class=\"navbtn\" data-page=\"taxonomy\"><i class=\"fa-solid fa-tags\" aria-hidden=\"true\"></i> Categories &amp; tags</button>\n   <button class=\"navbtn\" data-page=\"authors\" id=\"authorsNav\"><i class=\"fa-solid fa-users\" aria-hidden=\"true\"></i> Authors &amp; permissions</button>\n<button class=\"navbtn\" data-page=\"comments\" data-staff><i class=\"fa-solid fa-comments\" aria-hidden=\"true\"></i> \u00a0 Comments</button><button class=\"navbtn\" data-page=\"media\" data-staff><i class=\"fa-solid fa-images\" aria-hidden=\"true\"></i> \u00a0 Media library</button><button class=\"navbtn\" data-page=\"appearance\" data-staff><i class=\"fa-solid fa-sliders\" aria-hidden=\"true\"></i> \u00a0 Frontend appearance</button><button class=\"navbtn\" data-page=\"ads\" data-staff><i class=\"fa-solid fa-rectangle-ad\" aria-hidden=\"true\"></i> \u00a0 Ads &amp; banners</button><button class=\"navbtn\" data-page=\"seo\" data-staff><i class=\"fa-solid fa-magnifying-glass\" aria-hidden=\"true\"></i> \u00a0 SEO &amp; sitemap</button><button class=\"navbtn\" data-page=\"reports\" data-staff><i class=\"fa-solid fa-arrow-up-right-from-square\" aria-hidden=\"true\"></i> \u00a0 Reports</button>  </aside>\n  <main class=\"main\">\n   <section id=\"page-dashboard\"><div class=\"dashboard-heading\"><div><div class=\"eyebrow\">TAWON EDITORIAL SUITE</div><h1>Dashboard</h1><div class=\"muted\" id=\"dashboardDate\"></div></div><button class=\"primary\" data-go=\"editor\"><i class=\"fa-solid fa-plus\" aria-hidden=\"true\"></i> Write article</button></div>\n    <div class=\"stats\"><div class=\"card\"><div class=\"muted\">Total articles</div><div id=\"statAll\" class=\"statnum\">\u2014</div></div><div class=\"card\"><div class=\"muted\">Published</div><div id=\"statPublished\" class=\"statnum\">\u2014</div></div><div class=\"card\"><div class=\"muted\">Draft</div><div id=\"statDraft\" class=\"statnum\">\u2014</div></div><div class=\"card\"><div class=\"muted\">Pending review</div><div id=\"statReview\" class=\"statnum\">\u2014</div></div></div>\n<div class=\"dash-grid\"><div><div class=\"panel\"><div class=\"editorbar\"><h2>Reads \u00b7 last 7 days</h2><span class=\"badge\">Data recorded</span></div><div id=\"visitsChart\">Loading statistics\u2026</div><p class=\"muted\">Total reads recorded, not unique visitors.</p></div><div class=\"panel\"><h2>Quick menu</h2><div class=\"quick-grid\"><button data-go=\"editor\"><span><i class=\"fa-solid fa-pen-to-square\" aria-hidden=\"true\"></i></span>Write article</button><button data-go=\"taxonomy\"><span><i class=\"fa-solid fa-layer-group\" aria-hidden=\"true\"></i></span>Categories &amp; tags</button><button data-go=\"media\" data-staff><span><i class=\"fa-solid fa-images\" aria-hidden=\"true\"></i></span>Media library</button><button data-go=\"appearance\" data-staff><span><i class=\"fa-solid fa-sliders\" aria-hidden=\"true\"></i></span>Configure frontend</button></div></div></div><div class=\"panel\"><h2>Popular articles</h2><div id=\"adminPopular\">Loading\u2026</div></div></div>\n    <div class=\"panel\"><div class=\"editorbar\"><h2>Latest articles</h2><button class=\"primary\" data-go=\"editor\"><i class=\"fa-solid fa-plus\" aria-hidden=\"true\"></i> Write article</button></div><div id=\"recentList\" class=\"muted\">Loading\u2026</div></div>\n    <div class=\"panel\"><h2>Account status</h2><div id=\"roleInfo\">Checking permissions\u2026</div></div>\n   </section>\n   <section id=\"page-editor\" class=\"hidden\">\n    <div class=\"panel\">\n     <div class=\"notice\"><b>TAWON Publication Standard 1.0</b> \u00b7 Minimum 1,000 words, clear structure, sources, internal links, metadata, and thumbnails. <a href=\"/editorial-standard.html\" target=\"_blank\" rel=\"noopener\">Read full standards</a><button type=\"button\" id=\"checkEditorial\" class=\"light\">Check publication readiness</button><div id=\"editorialChecks\" role=\"status\"></div><label><input type=\"checkbox\" id=\"editorialAttestation\"> I have verified facts, attribution, originality, and image usage rights.</label></div><div class=\"editorbar\"><h2 id=\"editorHeading\">Write new article</h2><span id=\"wordCount\" class=\"wordcount\">0 / 1,000 words</span></div>\n     <form id=\"articleForm\">\n      <input id=\"articleId\" type=\"hidden\">\n      <div class=\"field\"><label for=\"title\">Article title *</label><input id=\"title\" required maxlength=\"180\" placeholder=\"Clear and engaging title\"></div>\n      <div class=\"grid\">\n       <div class=\"field\"><label for=\"slug\">URL Slug *</label><input id=\"slug\" required placeholder=\"article-title\"><small>Lowercase, numbers, and hyphens.</small></div>\n       <div class=\"field\"><label for=\"articleLanguage\">Article language *</label><select id=\"articleLanguage\"><option value=\"en\">English \u2014 international edition</option></select><small>English articles appear on the homepage. Content must match the selected language.</small></div><div class=\"field\"><label for=\"category\">Category *</label><select id=\"category\" required><option value=\"\">Select category</option></select></div>\n      </div>\n      <div class=\"field\"><label for=\"excerpt\">Summary / excerpt</label><textarea id=\"excerpt\" class=\"short\" maxlength=\"300\" placeholder=\"Article summary for news cards (max. 300 characters)\"></textarea></div>\n      <div class=\"field\"><label for=\"content\">Article content *</label><textarea id=\"content\" required style=\"min-height:340px\" placeholder=\"Use ## for subheadings, ### for sub-subheadings, - for lists, and blank lines to separate paragraphs.\"></textarea><small>Format: ## Subheading, ### Sub-subheading, - bullet list, 1. numbered list, and &gt; quote. Minimum 1,000 words to publish; drafts may be shorter.</small></div>\n      <div class=\"grid\">\n       <div class=\"field\"><label for=\"thumbnail\">Main thumbnail</label><input id=\"thumbnail\" type=\"file\" accept=\"image/jpeg,image/png,image/webp,image/avif\"><small>JPG, PNG, WebP, or AVIF; max. 5 MB. Public image alt text automatically uses the article title.</small><img id=\"thumbPreview\" class=\"thumb hidden\" alt=\"Thumbnail preview\"><input id=\"thumbnailUrl\" type=\"url\" placeholder=\"Or paste a hosted image URL\"></div>\n       <div class=\"field\"><label for=\"tagInput\">Article tags</label><input id=\"tagInput\" placeholder=\"Example: Purbalingga, Education, MSME\"><small>Separate tags with commas. Tags will be created automatically if they don't exist.</small><div id=\"tagChips\"></div></div>\n      </div>\n      <div class=\"grid\">\n       <div class=\"field\"><label for=\"metaTitle\">SEO title</label><input id=\"metaTitle\" maxlength=\"180\" placeholder=\"Leave blank to use article title\"><small id=\"metaTitleCount\">0/60 characters</small></div>\n       <div class=\"field\"><label for=\"metaDescription\">SEO description</label><textarea id=\"metaDescription\" class=\"short\" maxlength=\"200\" placeholder=\"Short description for search engines\"></textarea><small id=\"metaDescCount\">0/160 characters</small></div>\n       <div class=\"field\"><label for=\"canonical\">Canonical URL (optional)</label><input id=\"canonical\" type=\"url\" placeholder=\"https://tawon.my.id/artikel.html?slug=...\"></div>\n       <div class=\"field\"><label for=\"ogImage\">Open Graph image URL (optional)</label><input id=\"ogImage\" type=\"url\" placeholder=\"Leave blank to use thumbnail\"></div>\n      </div>\n      <div class=\"row\"><label><input type=\"checkbox\" id=\"featured\"> Make featured news</label></div>\n      <div class=\"actions\"><button class=\"light\" type=\"button\" id=\"saveDraft\">Save draft</button><button class=\"dark\" type=\"button\" id=\"sendReview\">Submit for review</button><button class=\"primary\" type=\"submit\" id=\"publishBtn\">Publish now</button><button class=\"light\" type=\"button\" id=\"resetEditor\">New article / reset</button></div>\n      <p class=\"muted\" style=\"font-size:12px\">Publish now is only available to admins/editors. Direct publication will make the article public if account policy allows.</p>\n     </form>\n    </div>\n   </section>\n   <section id=\"page-articles\" class=\"hidden\"><div class=\"panel\"><div class=\"editorbar\"><h2>All articles</h2><button class=\"primary\" data-go=\"editor\"><i class=\"fa-solid fa-plus\" aria-hidden=\"true\"></i> New article</button></div><div class=\"field\"><input id=\"articleSearch\" placeholder=\"Search article title...\"></div><div id=\"articleTable\" class=\"tablewrap\">Loading\u2026</div></div></section>\n   <section id=\"page-authors\" class=\"hidden\"><div class=\"panel\"><h2>Authors, users &amp; verification</h2><p class=\"muted\">Badges are active only after admin verification: blue for admin, green for author/editor, gray for regular users. Authors can only submit drafts/reviews unless admin enables direct publication.</p><div id=\"authorsList\">Loading\u2026</div></div></section>\n   <section id=\"page-taxonomy\" class=\"hidden\"><div class=\"grid\">\n    <div class=\"panel\"><h2>Category</h2><form id=\"categoryForm\"><div class=\"field\"><label for=\"categoryName\">Category name</label><input id=\"categoryName\" required maxlength=\"70\"></div><div class=\"field\"><label for=\"categoryDescription\">Description</label><input id=\"categoryDescription\" maxlength=\"180\"></div><button class=\"primary\">Add category</button></form><div id=\"categoryList\" style=\"margin-top:15px\"></div></div>\n    <div class=\"panel\"><h2>Tag</h2><form id=\"tagForm\"><div class=\"field\"><label for=\"tagName\">Tag name</label><input id=\"tagName\" required maxlength=\"70\"></div><button class=\"primary\">Add tag</button></form><div id=\"tagList\" style=\"margin-top:15px\"></div></div>\n   </div></section>\n\n<section id=\"page-comments\" class=\"hidden\"><div class=\"panel\"><h2>Comment moderation</h2><p class=\"muted\">List of public comments. Moderation actions are pending database permission approval.</p><div id=\"commentsList\">Loading\u2026</div></div></section>\n<section id=\"page-media\" class=\"hidden\"><div class=\"panel\"><h2>Media library</h2><p class=\"muted\">Article images from editorial storage. Max. 5 MB per image.</p><div class=\"row\"><input id=\"mediaFile\" type=\"file\" accept=\"image/jpeg,image/png,image/webp,image/avif\"><button id=\"mediaUpload\" class=\"primary\">Upload image</button></div><div id=\"mediaList\" class=\"media-grid\" style=\"margin-top:20px\"></div></div></section>\n<section id=\"page-appearance\" class=\"hidden\"><div class=\"panel\"><h2>Frontend appearance &amp; settings</h2><p class=\"muted\">Set site identity and appearance. Activation on public pages is pending configuration read permission approval.</p><div class=\"settings-preview\"><h3 id=\"brandPreview\">TAWON.MY.ID</h3><span id=\"tagPreview\">Latest, trusted news</span></div><form id=\"appearanceForm\"><div class=\"grid\"><div class=\"field\"><label for=\"settingName\">Site name</label><input id=\"settingName\" maxlength=\"80\" required></div><div class=\"field\"><label for=\"settingTagline\">Tagline</label><input id=\"settingTagline\" maxlength=\"160\"></div><div class=\"field\"><label for=\"settingColor\">Primary color</label><input id=\"settingColor\" type=\"color\" value=\"#facc15\"></div><div class=\"field\"><label for=\"settingLogo\">Logo URL (HTTPS)</label><input id=\"settingLogo\" type=\"url\" placeholder=\"https://...\"></div><div class=\"field full\"><label for=\"settingBreaking\">Special breaking news</label><input id=\"settingBreaking\" maxlength=\"240\" placeholder=\"Leave blank for main news title\"></div><div class=\"field full\"><label for=\"settingTrending\">Trending keywords (separate with commas)</label><input id=\"settingTrending\" maxlength=\"500\"></div><div class=\"field\"><label><input id=\"settingPopular\" type=\"checkbox\"> Show popular news</label></div><div class=\"field\"><label><input id=\"settingTrendVisible\" type=\"checkbox\"> Show trending</label></div></div><button class=\"primary\" type=\"submit\">Save frontend settings</button></form></div></section>\n<section id=\"page-ads\" class=\"hidden\"><div class=\"panel\"><h2>Ads &amp; banners</h2><p class=\"muted\">Image banner prepared for the area below the homepage header; public activation is pending approval. Use wide images; links must be HTTPS.</p><form id=\"adsForm\"><div class=\"field\"><label for=\"adTitle\">Ad title / description</label><input id=\"adTitle\" maxlength=\"120\"></div><div class=\"grid\"><div class=\"field\"><label for=\"adImage\">Image URL</label><input id=\"adImage\" type=\"url\"></div><div class=\"field\"><label for=\"adLink\">Destination link</label><input id=\"adLink\" type=\"url\"></div></div><p><label><input id=\"adEnabled\" type=\"checkbox\"> Enable banner</label></p><button class=\"primary\">Save banner</button></form></div></section>\n<section id=\"page-seo\" class=\"hidden\"><div class=\"panel\"><h2>SEO &amp; sitemap</h2><p class=\"muted\">Default description is used on the homepage. Article metadata is set via the article editor.</p><form id=\"seoForm\"><div class=\"field\"><label for=\"seoDescription\">Site description</label><textarea id=\"seoDescription\" maxlength=\"200\"></textarea></div><button class=\"primary\">Save SEO</button></form><hr style=\"border:0;border-top:1px solid #eee;margin:25px 0\"><div class=\"actions\"><button class=\"light\" id=\"downloadSitemap\">Download XML sitemap</button><a class=\"light\" href=\"/robots.txt\" target=\"_blank\" rel=\"noopener\">View robots.txt \u2197</a></div><p class=\"muted\">The live sitemap is generated automatically from published articles. This button downloads a separate XML copy.</p></div></section>\n<section id=\"page-reports\" class=\"hidden\"><div class=\"panel\"><h2>Editorial report</h2><p class=\"muted\">Export all articles accessible to your account, along with their status and view counts.</p><button class=\"primary\" id=\"exportCsv\">Download CSV report</button><div id=\"reportSummary\" style=\"margin-top:20px\"></div></div></section>\n  </main>\n </div>\n</div>\n<script>\n(() => {\nconst SUPABASE_URL='https://ajqwpbpaozlurqoxysjt.supabase.co';\nconst SUPABASE_KEY='sb_publishable_-XnVkQ5Jgi0ji47eizdS9g_XOY2Ao48';\nconst db=window.supabase.createClient(SUPABASE_URL,SUPABASE_KEY);\nconst $=id=>document.getElementById(id);\nlet user=null,profile=null,categories=[],allTags=[],articles=[],signupMode=false,editorStatus='draft',currentThumbUrl='';\nconst MIN_ARTICLE_WORDS=1000;\nfunction articleWordCount(raw){const doc=new DOMParser().parseFromString(String(raw||''),'text/html');doc.querySelectorAll('script,style').forEach(el=>el.remove());doc.querySelectorAll('p,h1,h2,h3,li,br').forEach(el=>el.append(' '));return (doc.body.textContent||'').replace(/^\\s*(?:#{1,6}|[-*>]|\\d+[.)])\\s+/gm,'').trim().split(/\\s+/).filter(Boolean).length;}\nfunction updateWordCount(){const count=articleWordCount($('content').value);$('wordCount').textContent=count.toLocaleString('en-US')+\" / 1,000 words\"+(count>=MIN_ARTICLE_WORDS?\" \u00b7 Ready to publish\":\" \u00b7 Less \"+(MIN_ARTICLE_WORDS-count).toLocaleString('en-US')+\" words\");$('wordCount').style.color=count>=MIN_ARTICLE_WORDS?'#15803d':'#9a6500';}\nconst slugify=s=>s.toLowerCase().normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,160);\nconst esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst notice=(msg,type='')=>{const n=$('globalNotice');n.textContent=msg;n.className='notice '+(type==='success'?'success':type==='error'?'error':'');n.classList.remove('hidden');window.scrollTo({top:0,behavior:'smooth'});};\nconst authNotice=(msg,type='')=>{const n=$('authNotice');n.textContent=msg;n.className='notice '+(type==='error'?'error':type==='success'?'success':'');n.classList.remove('hidden');};\nfunction showPage(page){document.querySelectorAll('[id^=\"page-\"]').forEach(x=>x.classList.add('hidden'));$('page-'+page).classList.remove('hidden');document.querySelectorAll('.navbtn').forEach(x=>x.classList.toggle('active',x.dataset.page===page));if(page==='articles')renderTable();if(page==='taxonomy')renderTaxonomy();if(page==='authors')loadAuthors();if(page==='comments')loadComments();if(page==='media')loadMedia();if(['appearance','ads','seo'].includes(page))loadSettings();if(page==='reports')$('reportSummary').textContent=\"Report includes articles based on account access permissions.\";}\ndocument.querySelectorAll('.navbtn').forEach(b=>b.addEventListener('click',()=>showPage(b.dataset.page)));\ndocument.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>{showPage(b.dataset.go);if(b.dataset.go==='editor')resetEditor();}));\n$('togglePassword').onclick=()=>{const input=$('authPassword'),show=input.type==='password';input.type=show?'text':'password';$('togglePassword').innerHTML='<i class=\"fa-solid '+(show?'fa-eye-slash':'fa-eye')+\"\\\" aria-hidden=\\\"true\\\"&gt;</i>\";$('togglePassword').setAttribute('aria-label',show?\"Hide password\":\"Show password\");$('togglePassword').setAttribute('aria-pressed',String(show));};\n$('toggleAuth').onclick=()=>{signupMode=!signupMode;$('authTitle').textContent=signupMode?\"Create author account\":\"Go to dashboard\";$('authSubtitle').textContent=signupMode?\"New accounts must be approved by an admin before they can publish.\":\"Manage articles, thumbnails, categories, tags, and SEO.\";$('authSubmit').textContent=signupMode?\"Register\":\"Login\";$('toggleAuth').textContent=signupMode?\"Back to login\":\"Register account\";$('authNotice').classList.add('hidden');};\n$('authForm').onsubmit=async e=>{e.preventDefault();$('authSubmit').disabled=true;try{const email=$('authEmail').value.trim(),password=$('authPassword').value;let r;if(signupMode)r=await db.auth.signUp({email,password,options:{emailRedirectTo:location.origin+'/admin.html'}});else r=await db.auth.signInWithPassword({email,password});if(r.error)throw r.error;if(signupMode&&!r.data.session){authNotice(\"Account created. Check your email for verification, then log in. After that, an admin needs to activate the editor/admin role.\",'success');}else{await boot(r.data.session?.user||r.data.user);}}catch(err){authNotice(err.code==='invalid_credentials'?\"Email or password does not match. Use Forgot password if you cannot remember it.\":err.code==='email_not_confirmed'?\"Email not yet verified. Open the latest confirmation link in your email.\":(err.message||\"Authentication failed.\"),'error');}finally{$('authSubmit').disabled=false;}};\n$('forgotPassword').onclick=()=>{ $('forgotEmail').value=$('authEmail').value.trim();$('loginView').classList.add('hidden');$('forgotView').classList.remove('hidden');$('forgotEmail').focus();};\n$('forgotBack').onclick=()=>{$('forgotView').classList.add('hidden');$('loginView').classList.remove('hidden');};\n$('forgotForm').onsubmit=async e=>{e.preventDefault();const btn=$('forgotSubmit');btn.disabled=true;btn.textContent='Mengirim\u2026';try{const email=$('forgotEmail').value.trim();const {error}=await db.auth.resetPasswordForEmail(email,{redirectTo:location.origin+'/admin.html'});if(error)throw error;showForgotNotice(\"If the email is registered, a reset link has been requested. Check your inbox and spam folder.\",'success');}catch(err){showForgotNotice(\"Could not send reset link: \"+(err.message||String(err)),'error');}finally{btn.disabled=false;btn.textContent=\"Send reset link\";}};\nfunction showForgotNotice(msg,type=''){const n=$('forgotNotice');n.textContent=msg;n.className='notice '+(type==='error'?'error':type==='success'?'success':'');n.classList.remove('hidden');}\n$('backToLogin').onclick=()=>location.href=location.pathname;\n$('resetForm').onsubmit=async e=>{e.preventDefault();const p=$('newPassword').value,confirm=$('confirmPassword').value;if(p.length<8){resetNotice(\"Password must be at least 8 characters.\",'error');return;}if(p!==confirm){resetNotice(\"Passwords do not match.\",'error');return;}const btn=$('resetSubmit');btn.disabled=true;try{const {error}=await db.auth.updateUser({password:p});if(error)throw error;resetNotice(\"Password updated successfully. You can return to the login page.\",'success');$('resetForm').classList.add('hidden');}catch(err){resetNotice(\"Failed to update password. Re-open the latest reset link from your email. \"+(err.message||String(err)),'error');}finally{btn.disabled=false;}};\nfunction resetNotice(msg,type=''){const n=$('resetNotice');n.textContent=msg;n.className='notice '+(type==='error'?'error':type==='success'?'success':'');n.classList.remove('hidden');}\nfunction showResetPage(){ $('loginView').classList.add('hidden');$('appView').classList.add('hidden');$('resetView').classList.remove('hidden');}\n$('googleLogin').onclick=async()=>{if(signupMode){authNotice(\"Back to login mode to use Google.\");return;}try{const {error}=await db.auth.signInWithOAuth({provider:'google',options:{redirectTo:location.origin+'/admin.html'}});if(error)throw error;}catch(err){authNotice(\"Google login not ready: \"+(err.message||String(err)),'error');}};\n$('logout').onclick=async()=>{await db.auth.signOut();location.reload();};\nasync function boot(u){user=u;if(!user){$('loginView').classList.remove('hidden');$('appView').classList.add('hidden');return;}const {data:p,error}=await db.from('profiles').select('*').eq('id',user.id).maybeSingle();profile=p;if(error){user=null;profile=null;$('loginView').classList.remove('hidden');$('appView').classList.add('hidden');authNotice(\"Login successful, but profile could not be loaded: \"+error.message+\". Please try logging in again.\",'error');return;}if(!profile){$('loginView').classList.remove('hidden');$('appView').classList.add('hidden');authNotice(\"Profile not yet available. Ensure email is verified and profile trigger is active. If necessary, the database admin must set up the profile for this account.\",'error');await db.auth.signOut();return;}\n$('loginView').classList.add('hidden');$('appView').classList.remove('hidden');$('userBadge').textContent=(profile.display_name||user.email)+' \u00b7 '+profile.role;\nif(profile.role==='user'){location.replace('/akun.html');return;}\n$('authorsNav').classList.toggle('hidden',profile.role!=='admin');const staff=['admin','editor'].includes(profile.role)||profile.can_publish===true;$('publishBtn').classList.toggle('hidden',!staff);$('roleInfo').innerHTML='<b>Role: '+esc(profile.role)+'</b><p class=\"muted\">'+(staff?\"This account has permission to publish articles.\":\"Authors can only save drafts or submit for review until an admin grants publication permission.\")+\"</p><p class=\\\"muted\\\">Point balance: \"+Number(profile.points_balance||0).toLocaleString('en-US')+\" points</p>\";\nawait loadData();document.querySelectorAll('[data-staff]').forEach(el=>el.classList.toggle('hidden',!['admin','editor'].includes(profile.role)));if(['admin','editor'].includes(profile.role)){loadInsights();loadSettings();}else{$('visitsChart').textContent=\"Reading statistics are available to admins/editors.\";$('adminPopular').textContent=\"Statistics available to admins/editors.\";}}\nasync function loadAuthors(){\n if(profile.role!=='admin'){$('authorsList').textContent=\"Only admins can manage author permissions.\";return;}\n const {data,error}=await db.from('profiles').select('id,display_name,role,can_publish,points_balance').order('display_name');\n if(error){$('authorsList').textContent=\"Failed to load author list: \"+error.message;return;}\n const verificationResult=await db.from('profile_verifications').select('user_id,verified');if(verificationResult.error){$('authorsList').textContent=\"Failed to load verification: \"+verificationResult.error.message;return;}const verifiedIds=new Set((verificationResult.data||[]).filter(v=>v.verified).map(v=>v.user_id));\n $('authorsList').innerHTML=\"<div class=\\\"tablewrap\\\"><table><thead><tr><th>Name</th><th>Role</th><th>Admin verification</th><th>Direct publication</th><th>Point balance</th><th>Action</th></tr></thead><tbody>\"+data.map(p=>'<tr data-author-row=\"'+p.id+\"\\\"&gt;<td>\"+esc(p.display_name||\"Author\")+\"</td><td><select data-role>\"+(p.role==='user'?'selected':'')+\"&gt;user</option>\"+(p.role==='author'?'selected':'')+\"&gt;author</option>\"+(p.role==='editor'?'selected':'')+\"&gt;editor</option>\"+(p.role==='admin'?'selected':'')+\"&gt;admin</option></select></td><td><label>\"+(verifiedIds.has(p.id)?'checked':'')+\"&gt; Verified</label></td><td>\"+(p.can_publish?'checked':'')+' '+(p.role==='author'?'':'disabled')+\" aria-label=\\\"Direct publication permission\\\"&gt;</td><td>\"+Number(p.points_balance||0).toLocaleString('en-US')+\"</td><td><button class=\\\"primary\\\" data-save-author>Save</button></td></tr>\").join('')+'</tbody></table></div>';\n $('authorsList').querySelectorAll('[data-role]').forEach(sel=>sel.onchange=()=>{const row=sel.closest('[data-author-row]');row.querySelector('[data-publish]').disabled=sel.value!=='author';});\n $('authorsList').querySelectorAll('[data-save-author]').forEach(btn=>btn.onclick=async()=>{const row=btn.closest('[data-author-row]'),id=row.dataset.authorRow,role=row.querySelector('[data-role]').value,can_publish=role==='author'&&row.querySelector('[data-publish]').checked;btn.disabled=true;const {error}=await db.from('profiles').update({role,can_publish}).eq('id',id);btn.disabled=false;if(error)return notice(\"Failed to save permission: \"+error.message,'error');const vr=await db.from('profile_verifications').upsert({user_id:id,verified:row.querySelector('[data-verified]').checked},{onConflict:'user_id'});if(vr.error)return notice(\"Role saved, but verification failed: \"+vr.error.message,'error');notice(\"Role and verification updated successfully.\",'success');loadAuthors();});\n}\nasync function loadData(){await Promise.all([loadCategories(),loadTags(),loadArticles()]);}\nasync function loadCategories(){const {data,error}=await db.from('categories').select('id,name,slug,description,is_active').order('name');if(error){notice(\"Failed to load categories: \"+error.message,'error');return;}categories=data||[];$('category').innerHTML=\"<option value=\\\"\\\">Select category</option>\"+categories.filter(c=>c.is_active).map(c=>'<option value=\"'+c.id+'\">'+esc(c.name)+'</option>').join('');renderTaxonomy();}\nasync function loadTags(){const {data,error}=await db.from('tags').select('id,name,slug').order('name');if(error){console.warn(error);return;}allTags=data||[];renderTaxonomy();}\nasync function loadArticles(){let q=db.from('articles').select('id,title,slug,status,created_at,published_at,view_count,is_featured,category_id,thumbnail_url,excerpt').order('created_at',{ascending:false}).limit(150);const {data,error}=await q;if(error){notice(\"Failed to load articles: \"+error.message,'error');return;}articles=data||[];renderStats();renderRecent();renderTable();}\nasync function renderStats(){for(const [id,status] of [['statAll',null],['statPublished','published'],['statDraft','draft'],['statReview','review']]){let q=db.from('articles').select('id',{count:'exact',head:true});if(status)q=q.eq('status',status);const r=await q;$(id).textContent=r.error?'\u2014':Number(r.count||0).toLocaleString('en-US');}}\nfunction renderRecent(){const list=articles.slice(0,6);$('recentList').innerHTML=list.length?list.map(a=>'<div class=\"row\" style=\"justify-content:space-between;padding:10px 0;border-bottom:1px solid #eee\"><div><b>'+esc(a.title)+'</b><div class=\"muted\" style=\"font-size:12px\">'+new Date(a.created_at).toLocaleString('en-US')+' \u00b7 '+esc(a.slug)+\"</div></div><div class=\\\"row\\\">\"+esc(a.status)+'\">'+esc(a.status)+\"</span>\"+a.id+\"\\\"&gt;Edit</button></div></div>\").join(''):\"No articles yet. Click Write article to create your first one.\";wireEditButtons();}\nfunction renderTable(){if(!$('articleTable'))return;const term=($('articleSearch')?.value||'').toLowerCase();const list=articles.filter(a=>a.title.toLowerCase().includes(term)||a.slug.toLowerCase().includes(term));$('articleTable').innerHTML=list.length?\"<table><thead><tr><th>Article</th><th>Status</th><th>Published</th><th>Action</th></tr></thead><tbody>\"+list.map(a=>'<tr><td><b>'+esc(a.title)+'</b><div class=\"muted\" style=\"font-size:12px\">'+esc(a.slug)+\"</div></td><td>\"+esc(a.status)+'\">'+esc(a.status)+'</span></td><td>'+ (a.published_at?new Date(a.published_at).toLocaleDateString('en-US'):'\u2014')+\"</td><td><div class=\\\"row\\\">\"+a.id+\"\\\"&gt;Edit</button>\"+(profile.role==='admin'?'<button class=\"danger\" data-delete=\"'+a.id+\"\\\"&gt;Delete</button>\":'')+'</div></td></tr>').join('')+'</tbody></table>':\"No matching articles.\";wireEditButtons();document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deleteArticle(b.dataset.delete));}\nfunction wireEditButtons(){document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editArticle(b.dataset.edit));}\n$('articleSearch').addEventListener('input',renderTable);\nfunction renderTaxonomy(){$('categoryList').innerHTML=categories.map(c=>'<div class=\"chip\">'+esc(c.name)+' <span class=\"muted\">/'+esc(c.slug)+'</span></div>').join('')||\"<p class=\\\"muted\\\">No categories yet.</p>\";$('tagList').innerHTML=allTags.slice(0,100).map(t=>'<span class=\"chip\">'+esc(t.name)+'</span>').join('')||\"<p class=\\\"muted\\\">No tags yet.</p>\";}\n$('categoryForm').onsubmit=async e=>{e.preventDefault();if(!['admin','editor'].includes(profile.role))return notice(\"Only admins/editors can add categories.\",'error');const name=$('categoryName').value.trim(),slug=slugify(name);const {error}=await db.from('categories').insert({name,slug,description:$('categoryDescription').value.trim()||null});if(error)return notice(\"Failed to create category: \"+error.message,'error');$('categoryForm').reset();await loadCategories();notice(\"Category added successfully.\",'success');};\n$('tagForm').onsubmit=async e=>{e.preventDefault();if(!['admin','editor'].includes(profile.role))return notice(\"Only admins/editors can add tags.\",'error');const name=$('tagName').value.trim();const {error}=await db.from('tags').insert({name,slug:slugify(name)});if(error)return notice(\"Failed to create tag: \"+error.message,'error');$('tagForm').reset();await loadTags();notice(\"Tag added successfully.\",'success');};\n$('title').addEventListener('input',()=>{if(!$('articleId').value)$('slug').value=slugify($('title').value);updateCounts();});\n$('content').addEventListener('input',updateWordCount);\n$('metaTitle').addEventListener('input',updateCounts);$('metaDescription').addEventListener('input',updateCounts);\nfunction inspectEditorialForm(){const r=window.TawonEditorial.inspect({title:$('title').value,slug:$('slug').value,content:$('content').value,excerpt:$('excerpt').value,meta_title:$('metaTitle').value||$('title').value,meta_description:$('metaDescription').value,thumbnail_url:$('thumbnailUrl').value||currentThumbUrl||($('thumbnail').files[0]?'https://pending-upload.local/image':'')});$('editorialChecks').textContent=(r.ready?\"Structure ready. Always verify facts, attribution, and image rights. \":\"Not ready: \")+r.errors.concat(r.warnings).join(' ');return r;}if($('checkEditorial'))$('checkEditorial').onclick=inspectEditorialForm;\nfunction updateCounts(){$('metaTitleCount').textContent=$('metaTitle').value.length+\"/60 characters\";$('metaDescCount').textContent=$('metaDescription').value.length+\"/160 characters\";}\n$('thumbnail').onchange=()=>{const f=$('thumbnail').files[0];if(!f){$('thumbPreview').classList.add('hidden');return;}if(f.size>5*1024*1024){notice(\"Maximum image size is 5 MB.\",'error');$('thumbnail').value='';return;}const url=URL.createObjectURL(f);$('thumbPreview').src=url;$('thumbPreview').classList.remove('hidden');};\n$('thumbnailUrl').addEventListener('input',()=>{const u=$('thumbnailUrl').value.trim();if(u){$('thumbPreview').src=u;$('thumbPreview').classList.remove('hidden');}});\nfunction resetEditor(){if($('editorialAttestation'))$('editorialAttestation').checked=false; $('articleForm').reset();$('articleId').value='';$('editorHeading').textContent=\"Write new article\";$('thumbPreview').classList.add('hidden');$('thumbnailUrl').value='';currentThumbUrl='';editorStatus='draft';updateWordCount();updateCounts(); }\n$('resetEditor').onclick=resetEditor;\nfunction editArticle(id){if($('editorialAttestation'))$('editorialAttestation').checked=false;const a=articles.find(x=>x.id===id);if(!a)return;db.from('articles').select('*,article_tags(tag_id,tags(id,name,slug))').eq('id',id).single().then(({data,error})=>{if(error)return notice(\"Failed to open article: \"+error.message,'error');if(profile.role==='author'&&data.author_id!==user.id)return notice(\"You do not have permission to edit this article.\",'error');$('articleId').value=data.id;$('articleLanguage').value=data.language||'en';$('title').value=data.title||'';$('slug').value=data.slug||'';$('category').value=data.category_id||'';$('excerpt').value=data.excerpt||'';$('content').value=data.content||'';$('thumbnailUrl').value=data.thumbnail_url||'';currentThumbUrl=data.thumbnail_url||'';$('metaTitle').value=data.meta_title||'';$('metaDescription').value=data.meta_description||'';$('canonical').value=data.canonical_url||'';$('ogImage').value=data.og_image_url||'';$('featured').checked=!!data.is_featured;$('tagInput').value=(data.article_tags||[]).map(x=>x.tags?.name).filter(Boolean).join(', ');editorStatus=data.status;$('editorHeading').textContent=\"Edit article\";$('thumbPreview').classList.toggle('hidden',!currentThumbUrl);if(currentThumbUrl)$('thumbPreview').src=currentThumbUrl;updateWordCount();updateCounts();showPage('editor');window.scrollTo({top:0,behavior:'smooth'});});}\nasync function uploadThumbnail(){const file=$('thumbnail').files[0];if(!file)return $('thumbnailUrl').value.trim()||currentThumbUrl||null;if(!['admin','editor'].includes(profile.role)&&profile.can_publish!==true)throw new Error(\"This account does not have permission to upload thumbnails.\");if(file.size>5*1024*1024)throw new Error(\"Maximum thumbnail size is 5 MB.\");const ext=(file.name.split('.').pop()||'jpg').toLowerCase().replace(/[^a-z0-9]/g,'');const path=new Date().toISOString().slice(0,10)+'/'+crypto.randomUUID()+'.'+ext;const {error}=await db.storage.from('article-thumbnails').upload(path,file,{contentType:file.type,upsert:false});if(error)throw error;return db.storage.from('article-thumbnails').getPublicUrl(path).data.publicUrl;}\nfunction parseTags(){return [...new Set($('tagInput').value.split(',').map(s=>s.trim()).filter(Boolean))].slice(0,15);}\nasync function ensureTagIds(names){const ids=[];for(const name of names){const slug=slugify(name);let t=allTags.find(x=>x.slug===slug);if(!t){const {data,error}=await db.from('tags').insert({name,slug}).select('id,name,slug').single();if(error){const retry=await db.from('tags').select('id,name,slug').eq('slug',slug).maybeSingle();if(retry.error||!retry.data)throw error;t=retry.data;}else{t=data;allTags.push(t);}}ids.push(t.id);}return ids;}\nasync function saveArticle(status){if(status==='published'&&!['admin','editor'].includes(profile.role)&&profile.can_publish!==true)throw new Error(\"This account does not have permission for direct publication from admin.\");const title=$('title').value.trim(),slug=slugify($('slug').value.trim()),content=$('content').value.trim(),categoryId=$('category').value;if(!title||!slug||!content||!categoryId)throw new Error(\"Title, slug, article content, and category are required.\");if(status==='published'&&articleWordCount(content)<MIN_ARTICLE_WORDS)throw new Error(\"Articles must be at least 1,000 words before publishing. Currently \"+articleWordCount(content)+\"  words. You can still save as a draft.\");$('slug').value=slug;const thumb=await uploadThumbnail();if(status==='published'){const checks=window.TawonEditorial.inspect({title,slug,content,excerpt:$('excerpt').value.trim(),meta_title:$('metaTitle').value.trim()||title,meta_description:$('metaDescription').value.trim(),thumbnail_url:thumb});$('editorialChecks').textContent=checks.errors.concat(checks.warnings).join(' ');if(!checks.ready)throw new Error(checks.errors.join(' '));if(!$('editorialAttestation')?.checked)throw new Error(\"Confirm editorial review before publishing.\");}const now=new Date().toISOString();const payload={language:$('articleLanguage').value,title,slug,excerpt:$('excerpt').value.trim()||null,content,thumbnail_url:thumb,category_id:categoryId,status,is_featured:$('featured').checked,meta_title:$('metaTitle').value.trim()||title,meta_description:$('metaDescription').value.trim()||$('excerpt').value.trim()||null,canonical_url:$('canonical').value.trim()||null,og_image_url:$('ogImage').value.trim()||thumb,published_at:status==='published'?(editorStatus==='published'?(articles.find(a=>a.id===$('articleId').value)?.published_at||now):now):null,updated_at:now};\nconst id=$('articleId').value;let saved;if(id){let q=db.from('articles').update(payload).eq('id',id);if(profile.role==='author')q=q.eq('author_id',user.id);const r=await q.select('id').single();if(r.error)throw r.error;saved=r.data;}else{payload.author_id=user.id;const r=await db.from('articles').insert(payload).select('id').single();if(r.error)throw r.error;saved=r.data;}\nconst tagIds=await ensureTagIds(parseTags());const del=await db.from('article_tags').delete().eq('article_id',saved.id);if(del.error)throw del.error;if(tagIds.length){const links=await db.from('article_tags').insert(tagIds.map(tag_id=>({article_id:saved.id,tag_id})));if(links.error)throw links.error;}\neditorStatus=status;await loadArticles();$('articleId').value=saved.id;$('editorHeading').textContent=\"Edit article\";return {id:saved.id,slug,status};}\n$('saveDraft').onclick=()=>doSave('draft');$('sendReview').onclick=()=>doSave('review');$('articleForm').onsubmit=e=>{e.preventDefault();doSave('published');};\nasync function doSave(status){const btns=[$('saveDraft'),$('sendReview'),$('publishBtn')];btns.forEach(b=>b.disabled=true);try{const a=await saveArticle(status);notice(status==='published'?\"Article published successfully. Article URL: \"+location.origin+'/artikel.html?slug='+encodeURIComponent(a.slug):status==='review'?\"Article saved and submitted for review.\":\"Draft article saved successfully.\",'success');if(status==='published')editorStatus='published';}catch(err){notice(\"Failed to save article: \"+(err.message||String(err)),'error');}finally{btns.forEach(b=>b.disabled=false);}}\nasync function deleteArticle(id){if(profile.role!=='admin')return notice(\"Only admins can delete articles.\",'error');if(!confirm(\"Delete this article? This action cannot be undone.\"))return;const {error}=await db.from('articles').delete().eq('id',id);if(error)return notice(\"Failed to delete: \"+error.message,'error');await loadArticles();notice(\"Article deleted.\",'success');}\n\nconst siteDefaults={name:'TAWON.MY.ID',tagline:\"Latest, trusted news\",color:'#facc15',logo:'',breaking:'',trending:'Indonesia,Ekonomi,Teknologi,Pendidikan',popular:true,trending_visible:true,description:\"Latest news from TAWON.MY.ID\",ad:{enabled:false,title:'',image:'',link:''}};\nlet siteConfig={...siteDefaults},configLoaded=false;\n$('dashboardDate').textContent=new Intl.DateTimeFormat('en-US',{dateStyle:'full'}).format(new Date());\nfunction httpsUrl(v){if(!v)return '';const u=new URL(v);if(u.protocol!=='https:')throw new Error(\"URL must use HTTPS.\");return u.href;}\nasync function loadSettings(){const r=await db.from('site_settings').select('key,value').in('key',['frontend_config','site_name','tagline']);if(r.error)return notice(\"Failed to load settings: \"+r.error.message,'error');siteConfig={...siteDefaults};for(const row of r.data||[]){if(row.key==='site_name')siteConfig.name=row.value;if(row.key==='tagline')siteConfig.tagline=row.value;if(row.key==='frontend_config')siteConfig={...siteConfig,...row.value};}configLoaded=true;const c=siteConfig;for(const [id,key] of [['settingName','name'],['settingTagline','tagline'],['settingColor','color'],['settingLogo','logo'],['settingBreaking','breaking'],['settingTrending','trending'],['seoDescription','description']])$(id).value=c[key]||'';$('settingPopular').checked=c.popular!==false;$('settingTrendVisible').checked=c.trending_visible!==false;const ad=c.ad||{};for(const [id,key]of [['adTitle','title'],['adImage','image'],['adLink','link']])$(id).value=ad[key]||'';$('adEnabled').checked=!!ad.enabled;previewBrand();document.querySelectorAll('#appearanceForm button,#adsForm button,#seoForm button').forEach(b=>b.disabled=profile.role!=='admin');}\nfunction previewBrand(){$('brandPreview').textContent=$('settingName').value;$('tagPreview').textContent=$('settingTagline').value;$('brandPreview').parentElement.style.borderColor=$('settingColor').value;}\n['settingName','settingTagline','settingColor'].forEach(id=>$(id).oninput=previewBrand);\nasync function persistConfig(patch,form){if(profile.role!=='admin')return notice(\"Only admins can change site settings.\",'error');if(!configLoaded)return notice(\"Reload settings before saving.\",'error');const btn=form.querySelector('button');btn.disabled=true;try{const latest=await db.from('site_settings').select('value').eq('key','frontend_config').maybeSingle();if(latest.error)throw latest.error;const next={...siteDefaults,...siteConfig,...latest.data?.value,...patch};const r=await db.from('site_settings').upsert({key:'frontend_config',value:next,updated_at:new Date().toISOString()}).select('key').single();if(r.error)throw r.error;siteConfig=next;notice(\"Settings saved. Changes to public pages are pending configuration permission activation.\",'success');}catch(e){notice(e.message,'error');}finally{btn.disabled=false;}}\n$('appearanceForm').onsubmit=e=>{e.preventDefault();try{persistConfig({name:$('settingName').value.trim(),tagline:$('settingTagline').value.trim(),color:$('settingColor').value,logo:httpsUrl($('settingLogo').value.trim()),breaking:$('settingBreaking').value.trim(),trending:$('settingTrending').value.trim(),popular:$('settingPopular').checked,trending_visible:$('settingTrendVisible').checked},e.target);}catch(err){notice(err.message,'error');}};\n$('adsForm').onsubmit=e=>{e.preventDefault();try{const ad={enabled:$('adEnabled').checked,title:$('adTitle').value.trim(),image:httpsUrl($('adImage').value.trim()),link:httpsUrl($('adLink').value.trim())};if(ad.enabled&&(!ad.image||!ad.link))throw new Error(\"Enter image URL and destination link to activate banner.\");persistConfig({ad},e.target);}catch(err){notice(err.message,'error');}};\n$('seoForm').onsubmit=e=>{e.preventDefault();persistConfig({description:$('seoDescription').value.trim()},e.target);};\nasync function loadInsights(){const r=await db.from('articles').select('title,slug,thumbnail_url,view_count').eq('status','published').order('view_count',{ascending:false}).limit(5);$('adminPopular').innerHTML=r.error?esc(r.error.message):(r.data||[]).map((a,i)=>'<div class=\"rank-row\"><b style=\"color:#bd9200\">'+(i+1)+\"</b><div><strong>\"+encodeURIComponent(a.slug)+'\" target=\"_blank\" rel=\"noopener\">'+esc(a.title)+'</a></strong><small>'+Number(a.view_count||0).toLocaleString('en-US')+\" reads</small></div></div>\").join('')||\"No articles yet.\";const start=new Date();start.setDate(start.getDate()-6);start.setHours(0,0,0,0);let rows=[],offset=0;try{while(true){const v=await db.from('article_views').select('viewed_at').gte('viewed_at',start.toISOString()).order('viewed_at').range(offset,offset+999);if(v.error)throw v.error;rows.push(...v.data);if(v.data.length<1000)break;offset+=1000;}const days=Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);const key=d.toLocaleDateString('en-CA',{timeZone:'Asia/Jakarta'});return {label:d.toLocaleDateString('en-US',{day:'numeric',month:'short'}),n:rows.filter(x=>new Date(x.viewed_at).toLocaleDateString('en-CA',{timeZone:'Asia/Jakarta'})===key).length};});const max=Math.max(1,...days.map(d=>d.n));$('visitsChart').innerHTML='<div class=\"chart-bars\">'+days.map(d=>'<div class=\"chart-col\"><b>'+d.n+\"</b>\"+Math.max(2,d.n/max*135)+\"px\\\"&gt;</i>\"+esc(d.label)+'</div>').join('')+'</div>';}catch(e){$('visitsChart').textContent=\"Statistics could not be loaded: \"+e.message;}}\nasync function loadComments(){const r=await db.from('article_comments').select('id,display_name,body,status,created_at').order('created_at',{ascending:false}).limit(100);if(r.error){$('commentsList').textContent=r.error.message;return;}$('commentsList').innerHTML=(r.data||[]).map(c=>'<div class=\"rank-row\"><div style=\"flex:1\"><strong>'+esc(c.display_name)+'</strong><p>'+esc(c.body)+'</p><small>'+esc(c.status)+' \u00b7 '+new Date(c.created_at).toLocaleString('en-US')+\"</small></div>\"+c.id+'\" data-next=\"'+(c.status==='visible'?'hidden':'visible')+'\">'+(c.status==='visible'?\"Hide\":\"Show\")+'</button></div>').join('')||\"No comments yet.\";}\n\nasync function loadMedia(){const r=await db.storage.from('article-thumbnails').list('',{limit:100,sortBy:{column:'created_at',order:'desc'}});if(r.error){$('mediaList').textContent=r.error.message;return;}let files=[];for(const item of r.data||[]){if(item.id)files.push(item);else{const folder=await db.storage.from('article-thumbnails').list(item.name,{limit:100});if(!folder.error)files.push(...folder.data.filter(x=>x.id).map(x=>({...x,name:item.name+'/'+x.name})));}}$('mediaList').innerHTML=files.length?files.map(f=>{const url=db.storage.from('article-thumbnails').getPublicUrl(f.name).data.publicUrl;return \"<div class=\\\"media-item\\\">\"+esc(url)+\"\\\" alt=\\\"Editorial media\\\"&gt;<p class=\\\"muted\\\">\"+esc(f.name.split('/').pop())+\"</p>\"+esc(url)+'\"><button class=\"light\" data-use-media=\"'+esc(url)+\"\\\"&gt;Use in article</button></div>\";}).join(''):\"No images yet. Upload your first image.\";$('mediaList').querySelectorAll('[data-use-media]').forEach(b=>b.onclick=()=>{$('thumbnailUrl').value=b.dataset.useMedia;$('thumbnailUrl').dispatchEvent(new Event('input'));showPage('editor');notice(\"Image selected for article editor.\",'success');});}\n$('mediaUpload').onclick=async()=>{const f=$('mediaFile').files[0],b=$('mediaUpload');if(!f)return notice(\"Please select an image first.\",'error');if(!['image/jpeg','image/png','image/webp','image/avif'].includes(f.type)||f.size>5*1024*1024)return notice(\"Select JPG, PNG, WebP, or AVIF images (max 5 MB).\",'error');b.disabled=true;try{const ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp','image/avif':'avif'}[f.type];const r=await db.storage.from('article-thumbnails').upload(new Date().toISOString().slice(0,10)+'/'+crypto.randomUUID()+'.'+ext,f,{contentType:f.type});if(r.error)throw r.error;$('mediaFile').value='';await loadMedia();notice(\"Image uploaded successfully.\",'success');}catch(e){notice(e.message,'error');}finally{b.disabled=false;}};\nasync function allArticles(){let rows=[];for(let n=0;;n+=1000){const r=await db.from('articles').select('id,title,slug,status,published_at,view_count,created_at').order('id').range(n,n+999);if(r.error)throw r.error;rows.push(...r.data);if(r.data.length<1000)return rows;}}\nfunction download(name,text,type){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}\n$('exportCsv').onclick=async()=>{try{const rows=await allArticles(),cell=v=>'\"'+String(v??'').replace(/^[=+@\\-]/,\"'$&\").replace(/\"/g,'\"\"')+'\"';download('laporan-tawon.csv','\\ufeff'+[[\"Title\",'Slug','Status',\"Published\",\"Views\"],...rows.map(a=>[a.title,a.slug,a.status,a.published_at,a.view_count])].map(r=>r.map(cell).join(',')).join('\\r\\n'),'text/csv;charset=utf-8');}catch(e){notice(e.message,'error');}};\n$('downloadSitemap').onclick=async()=>{try{const rows=await allArticles(),xml=v=>String(v).replace(/[<>&'\\\"]/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;',\"'\":'&apos;','\"':'&quot;'}[c]));download('sitemap.xml',\"<urlset xmlns=\\\"http://www.sitemaps.org/schemas/sitemap/0.9\\\"><url><loc>https://tawon.my.id/</loc></url>\"+rows.filter(a=>a.status==='published'&&a.published_at&&new Date(a.published_at)<=new Date()).map(a=>'<url><loc>'+xml('https://tawon.my.id/artikel.html?slug='+encodeURIComponent(a.slug))+'</loc></url>').join('')+'</urlset>','application/xml');}catch(e){notice(e.message,'error');}};\n\ndb.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY'){showResetPage();return;}if(event==='SIGNED_OUT'){user=null;profile=null;$('appView').classList.add('hidden');$('loginView').classList.remove('hidden');return;}if(session?.user&&!user)setTimeout(()=>boot(session.user).catch(err=>authNotice(\"Dashboard could not be loaded: \"+err.message,'error')),0);});\nif(location.hash.includes('type=recovery')||new URLSearchParams(location.search).get('mode')==='reset'){showResetPage();}db.auth.getSession().then(({data})=>{if(location.hash.includes('type=recovery')||new URLSearchParams(location.search).get('mode')==='reset')showResetPage();else boot(data.session?.user||null);});\n})();\n</script>\n</body></html>\n";
